import Base

type R_Camera is Data:
  R_Camera{x: F32,y: F32,z: F32,yaw: F32,pitch: F32}

type R_Block is Data:
  R_Block{x: F32,y: F32,z: F32,state: U32,material: U32}

type R_Snapshot is Data:
  R_Snapshot{tick: Nat,revision: Nat,blocks: List<&2,R_Block>,camera: R_Camera}

type M_Vec3 is Data:
  M_Vec3{x:F32,y:F32,z:F32}

type M_UV is Data:
  M_UV{u:F32,v:F32}

type M_Vertex is Data:
  M_Vertex{position:M_Vec3,uv:M_UV}

type M_Mode is Data:
  M_Opaque{}
  M_Cutout{threshold:U32}
  M_Translucent{}

type M_Address is Data:
  M_Clamp{}
  M_Repeat{}

type M_Cull is Data:
  M_NoCull{}
  M_Back{}

type M_Material is Data:
  M_Material{texture:U32,tint:U32,light:U32,shade:F32,mode:M_Mode,address:M_Address}

type M_Quad is Data:
  M_Quad{a:M_Vertex,b:M_Vertex,c:M_Vertex,d:M_Vertex,material:M_Material,cull:M_Cull,order:U32}

type M_Settings is Data:
  M_Settings{near:F32,far:F32,scale:F32,background:U32}

type M_Scene is Data:
  M_Scene{camera:R_Camera,quads:List<&2,M_Quad>,settings:M_Settings}

type B_Direction is Data:
  B_Down{}
  B_Up{}
  B_North{}
  B_South{}
  B_West{}
  B_East{}

type K_Layer is Data:
  K_Solid{}
  K_Cutout{}
  K_Translucent{}

type K_Baked is Data:
  K_Baked{a:M_Vertex,b:M_Vertex,c:M_Vertex,d:M_Vertex,direction:B_Direction,
    cullface:Maybe<&2,B_Direction>,sprite:String,texture:U32,tint_index:U32,
    light_emission:U32,shade_override:Maybe<&2,B_Direction>,layer:K_Layer,
    force_translucent:Bool,animated:Bool,default_shade:F32,nether_shade:F32}

type K_Appearance is Data:
  K_Appearance{tint:U32,light:U32,address:M_Address,cull:M_Cull,nether:Bool,cutout_threshold:U32}

def P_choose(-A: Type, yes: A, no: A, condition: Bool) -> A:
  match condition:
    case True{}: yes
    case False{}: no

def M_defaults() -> M_Settings:
  M_Settings{0.0001,64.0,0.7002075382,4284784875}

def M_finite(+value:F32) -> Bool:
  U32.is_ne(U32.and(F32.bits(value),2139095040),2139095040)

def M_bounded(+value:F32,limit:F32) -> Bool:
  M_finite(value) && F32.is_le(F32.abs(value),limit)

def M_valid_position(value:M_Vec3) -> Bool:
  M_Vec3{x,y,z} = value
  M_bounded(x,4096.0) && M_bounded(y,4096.0) && M_bounded(z,4096.0)

def M_valid_uv(value:M_UV) -> Bool:
  M_UV{u,v} = value
  M_bounded(u,65536.0) && M_bounded(v,65536.0)

def M_valid_vertex(value:M_Vertex) -> Bool:
  M_Vertex{position,uv} = value
  M_valid_position(position) && M_valid_uv(uv)

def M_valid_mode(mode:M_Mode) -> Bool:
  match mode:
    case M_Cutout{threshold}: U32.is_le(threshold,255)
    case _: True{}

def M_valid_material(value:M_Material,count:U32) -> Bool:
  M_Material{texture,tint,+light,+shade,mode,address} = value
  U32.is_lt(texture,count) && U32.is_eq(U32.shrn(light,24n),255) && M_finite(shade) && F32.is_ge(shade,0.0) && F32.is_le(shade,1.0) && M_valid_mode(mode)

def M_translucent(mode:M_Mode) -> U32:
  match mode:
    case M_Translucent{}: 1
    case _: 0

def M_material_translucent(material:M_Material) -> U32:
  M_Material{texture,tint,light,shade,mode,address} = material
  M_translucent(mode)

def M_settings_valid(settings:M_Settings) -> Bool:
  M_Settings{+near,+far,+scale,background} = settings
  M_finite(near) && M_finite(far) && M_finite(scale) && F32.is_gt(near,0.0) && F32.is_gt(far,near) && F32.is_le(far,4096.0) && F32.is_gt(scale,0.0) && F32.is_le(scale,8.0) && U32.is_eq(U32.shrn(background,24n),255)

def M_camera_valid(camera:R_Camera) -> Bool:
  R_Camera{x,y,z,yaw,pitch} = camera
  M_bounded(x,4096.0) && M_bounded(y,4096.0) && M_bounded(z,4096.0) && M_bounded(yaw,65536.0) && M_bounded(pitch,65536.0)

def K_mesh_mode(layer:K_Layer,threshold:U32) -> M_Mode:
  match layer:
    case K_Solid{}: M_Opaque{}
    case K_Cutout{}: M_Cutout{threshold}
    case K_Translucent{}: M_Translucent{}

def K_mesh(value:K_Baked,appearance:K_Appearance,order:U32) -> M_Quad:
  K_Baked{a,b,c,d,direction,cf,sprite,texture,tint_index,emission,override,layer,force,animated,ds,ns} = value
  K_Appearance{tint,light,address,cull,nether,threshold} = appearance
  M_Quad{a,b,c,d,M_Material{texture,tint,light,P_choose(F32,ns,ds,nether),K_mesh_mode(layer,threshold),address},cull,order}


# Pure camera-relative snapshot producer. Model/state selection and lighting
# remain explicit inputs. Neighbor cull groups never discard a face here.
type Tint is Data:
  Tint{index:U32,color:U32}
type Appearance is Data:
  Appearance{tints:List<&2,Tint>,light:U32,address:M_Address,cull:M_Cull,
    nether:Bool,cutout_threshold:U32}
type Binding is Data:
  Binding{state:U32,baked:List<&2,K_Baked>,appearance:Appearance}
type Frame is Data:
  Frame{width:U32,height:U32,settings:M_Settings}
type Limits is Data:
  Limits{max_blocks:U32,max_bindings:U32,max_quads:U32,
    max_translucent:U32,max_tints:U32}
type Error is Data:
  Error{code:String,state:U32}
type Accumulator is Data:
  Accumulator{reversed:List<&2,M_Quad>,count:U32,translucent:U32}
type Surface is Data:
  Surface{material:M_Material,cull:M_Cull,order:U32}

def defaults() -> Limits:
  Limits{4096,1024,4096,64,256}
def appearance() -> Appearance:
  Appearance{[],4294967295,M_Clamp{},M_Back{},False{},128}
def frame(width:U32,height:U32) -> Frame:
  Frame{width,height,M_defaults()}

def limits_valid(value:Limits) -> Bool:
  Limits{blocks,bindings,quads,translucent,tints} = value
  U32.is_le(blocks,4096) && U32.is_le(bindings,4096) &&
    U32.is_le(quads,4096) && U32.is_le(translucent,64) && U32.is_le(tints,4096)

def relative_camera(+camera:R_Camera) -> Bool:
  R_Camera{x,y,z,yaw,pitch} = camera
  M_camera_valid(camera) && F32.is_eq(x,0.0) && F32.is_eq(y,0.0) && F32.is_eq(z,0.0)

def frame_valid(value:Frame) -> Bool:
  Frame{+width,+height,settings} = value
  U32.is_ge(width,4) && U32.is_ge(height,4) && U32.is_le(width,1024) &&
    U32.is_le(height,1024) && M_settings_valid(settings)

def fits(-A:Data,values:List<&2,A>,+remaining:U32) -> Bool:
  match values:
    case Nil{}: True{}
    case head <> tail: U32.is_gt(remaining,0) && fits(A,tail,U32.sub(remaining,1))

def has_tint(values:List<&2,Tint>,+index:U32) -> Bool:
  match values:
    case Nil{}: False{}
    case Tint{current,color} <> tail: U32.is_eq(current,index) || has_tint(tail,index)

def tints_valid(values:List<&2,Tint>,+remaining:U32) -> Bool:
  match values:
    case Nil{}: True{}
    case Tint{+index,color} <> +tail:
      U32.is_gt(remaining,0) && U32.is_ne(index,4294967295) &&
        Bool.not(has_tint(tail,index)) && tints_valid(tail,U32.sub(remaining,1))

def appearance_valid(value:Appearance,+max_tints:U32) -> Bool:
  Appearance{+tints,light,address,cull,nether,threshold} = value
  U32.is_eq(U32.shrn(light,24n),255) && U32.is_le(threshold,255) &&
    fits(Tint,tints,max_tints) && tints_valid(tints,max_tints)

def tint_lookup(values:List<&2,Tint>,+index:U32) -> Maybe<&2,U32>:
  match values:
    case Nil{}: None{}
    case Tint{current,color} <> tail:
      P_choose(Maybe<&2,U32>,Some{color},tint_lookup(tail,index),U32.is_eq(current,index))

def tint(value:Appearance,+index:U32) -> Maybe<&2,U32>:
  Appearance{tints,light,address,cull,nether,threshold} = value
  P_choose(Maybe<&2,U32>,Some{4294967295},tint_lookup(tints,index),U32.is_eq(index,4294967295))

def mesh_appearance(value:Appearance,color:U32) -> K_Appearance:
  Appearance{tints,light,address,cull,nether,threshold} = value
  K_Appearance{color,light,address,cull,nether,threshold}

def translate_vertex(value:M_Vertex,origin:M_Vec3) -> M_Vertex:
  match value origin:
    case M_Vertex{M_Vec3{x,y,z},uv} M_Vec3{ox,oy,oz}:
      M_Vertex{M_Vec3{F32.add(x,ox),F32.add(y,oy),F32.add(z,oz)},uv}

def translate_quad(value:M_Quad,+origin:M_Vec3) -> M_Quad:
  M_Quad{a,b,c,d,material,cull,order} = value
  M_Quad{translate_vertex(a,origin),translate_vertex(b,origin),
    translate_vertex(c,origin),translate_vertex(d,origin),material,cull,order}

def vertex_uv(value:M_Vertex) -> M_UV:
  M_Vertex{position,uv} = value
  uv
def surface(value:M_Quad) -> Surface:
  M_Quad{a,b,c,d,material,cull,order} = value
  Surface{material,cull,order}

law translated_vertex_preserves_uv:
  for position:M_Vec3
  for +uv:M_UV
  for origin:M_Vec3
  {vertex_uv(translate_vertex(M_Vertex{position,uv},origin)) == uv : M_UV}

def translated_vertex_preserves_uv(position,uv,origin):
  match position origin:
    case M_Vec3{x,y,z} M_Vec3{ox,oy,oz}: {==}

law translated_quad_preserves_surface:
  for a:M_Vertex
  for b:M_Vertex
  for c:M_Vertex
  for d:M_Vertex
  for +material:M_Material
  for +cull:M_Cull
  for +order:U32
  for origin:M_Vec3
  {surface(translate_quad(M_Quad{a,b,c,d,material,cull,order},origin)) == Surface{material,cull,order} : Surface}

def translated_quad_preserves_surface(a,b,c,d,material,cull,order,origin):
  {==}

def quad_valid(value:M_Quad,textures:U32) -> Bool:
  M_Quad{a,b,c,d,material,cull,order} = value
  M_valid_vertex(a) && M_valid_vertex(b) && M_valid_vertex(c) &&
    M_valid_vertex(d) && M_valid_material(material,textures)

def forced_layer(layer:K_Layer,force:Bool) -> Bool:
  match layer:
    case K_Translucent{}: True{}
    case _: Bool.not(force)

def baked_error(+value:K_Baked,+appearance:Appearance,textures:U32) -> String:
  K_Baked{a,b,c,d,direction,cf,sprite,texture,+index,emission,override,+layer,+force,+animated,ds,ns} = value
  P_choose(String,"UnsupportedAnimation",P_choose(String,"BakedMetadata",
    P_choose(String,"MissingTint",P_choose(String,"BakedQuad","",
      Bool.not(quad_valid(K_mesh(value,mesh_appearance(appearance,4294967295),0),textures))),
      Maybe.is_none(&2,U32,tint(appearance,index))),
    U32.is_gt(emission,15) || Bool.not(forced_layer(layer,force))),animated)

def checked_baked(error:String) -> Result<&2,&2,String,Unit>:
  match error:
    case "": Done{Unit{}}
    case error: Fail{error}

def baked_check(values:List<&2,K_Baked>,+appearance:Appearance,+textures:U32,+remaining:U32) -> Result<&2,&2,String,U32>:
  match values:
    case Nil{}: Done{remaining}
    case head <> tail:
      do Result<&2,&2,String,U32>:
        unit : Unit <- checked_baked(baked_error(head,appearance,textures))
        P_choose(Result<&2,&2,String,U32>,Fail{"SourceQuadLimit"},
          baked_check(tail,appearance,textures,U32.sub(remaining,1)),U32.is_eq(remaining,0))

def has_state(bindings:List<&2,Binding>,+state:U32) -> Bool:
  match bindings:
    case Nil{}: False{}
    case Binding{current,baked,appearance} <> tail: U32.is_eq(current,state) || has_state(tail,state)

def bindings_check(bindings:List<&2,Binding>,+textures:U32,+remaining:U32,+quads:U32,+max_tints:U32) -> Result<&2,&2,String,Unit>:
  match bindings:
    case Nil{}: Done{Unit{}}
    case Binding{+state,baked,+appearance} <> +tail:
      do Result<&2,&2,String,Unit>:
        unit : Unit <- checked_baked(P_choose(String,"BindingLimit",P_choose(String,"DuplicateState",
          P_choose(String,"Appearance","",Bool.not(appearance_valid(appearance,max_tints))),
          has_state(tail,state)),U32.is_eq(remaining,0)))
        left : U32 <- baked_check(baked,appearance,textures,quads)
        bindings_check(tail,textures,U32.sub(remaining,1),left,max_tints)

def bindings_error(result:Result<&2,&2,String,Unit>) -> String:
  match result:
    case Fail{error}: error
    case Done{unit}: ""

def bindings_gate(valid:Bool,bindings:List<&2,Binding>,textures:U32,remaining:U32,quads:U32,max_tints:U32) -> String:
  match valid:
    case False{}: "BindingLimit"
    case True{}: bindings_error(bindings_check(bindings,textures,remaining,quads,max_tints))

def lookup(bindings:List<&2,Binding>,+state:U32) -> Maybe<&2,Binding>:
  match bindings:
    case Nil{}: None{}
    case +head <> tail:
      Binding{current,baked,appearance} = head
      P_choose(Maybe<&2,Binding>,Some{head},lookup(tail,state),U32.is_eq(current,state))

def add_valid(valid:Bool,+quad:M_Quad,acc:Accumulator,+limits:Limits,+state:U32) -> Result<&2,&2,Error,Accumulator>:
  match valid:
    case False{}: Fail{Error{"TranslatedQuad",state}}
    case True{}:
      M_Quad{a,b,c,d,+material,cull,order} = quad
      Accumulator{reversed,+count,+translucent} = acc
      Limits{blocks,bindings,+max_quads,+max_translucent,tints} = limits
      P_choose(Result<&2,&2,Error,Accumulator>,Fail{Error{"QuadLimit",state}},
        P_choose(Result<&2,&2,Error,Accumulator>,Fail{Error{"TranslucentLimit",state}},
          Done{Accumulator{quad <> reversed,U32.inc(count),U32.add(translucent,M_material_translucent(material))}},
          U32.is_ge(translucent,max_translucent) && U32.is_eq(M_material_translucent(material),1)),
        U32.is_ge(count,max_quads))

def translated(color:Maybe<&2,U32>,value:K_Baked,+appearance:Appearance,+origin:M_Vec3,+acc:Accumulator,textures:U32,limits:Limits,state:U32) -> Result<&2,&2,Error,Accumulator>:
  match color:
    case None{}: Fail{Error{"MissingTint",state}}
    case Some{color}:
      Accumulator{reversed,count,layers} = acc
      +quad = translate_quad(K_mesh(value,mesh_appearance(appearance,color),count),origin)
      add_valid(quad_valid(quad,textures),quad,acc,limits,state)

def baked_produce(values:List<&2,K_Baked>,+appearance:Appearance,+origin:M_Vec3,acc:Accumulator,+textures:U32,+limits:Limits,+state:U32) -> Result<&2,&2,Error,Accumulator>:
  match values:
    case Nil{}: Done{acc}
    case +head <> tail:
      K_Baked{a,b,c,d,direction,cf,sprite,texture,index,emission,override,layer,force,animated,ds,ns} = head
      do Result<&2,&2,Error,Accumulator>:
        acc : Accumulator <- translated(tint(appearance,index),head,appearance,origin,acc,textures,limits,state)
        baked_produce(tail,appearance,origin,acc,textures,limits,state)

def block_bound(block:R_Block) -> Bool:
  R_Block{x,y,z,state,material} = block
  M_valid_position(M_Vec3{x,y,z})

def bound_block(valid:Bool,block:R_Block,binding:Maybe<&2,Binding>,acc:Accumulator,textures:U32,limits:Limits) -> Result<&2,&2,Error,Accumulator>:
  match valid:
    case False{}: Fail{Error{"BlockOrigin",0}}
    case True{}:
      R_Block{x,y,z,+state,material} = block
      match binding:
        case None{}: Fail{Error{"MissingState",state}}
        case Some{Binding{current,baked,appearance}}:
          baked_produce(baked,appearance,M_Vec3{x,y,z},acc,textures,limits,state)

def blocks_produce(blocks:List<&2,R_Block>,+bindings:List<&2,Binding>,acc:Accumulator,+textures:U32,+limits:Limits,+remaining:U32) -> Result<&2,&2,Error,Accumulator>:
  match blocks:
    case Nil{}: Done{acc}
    case +head <> tail:
      R_Block{x,y,z,state,material} = head
      do Result<&2,&2,Error,Accumulator>:
        acc : Accumulator <- P_choose(Result<&2,&2,Error,Accumulator>,Fail{Error{"BlockLimit",state}},
          bound_block(block_bound(head),head,lookup(bindings,state),acc,textures,limits),U32.is_eq(remaining,0))
        blocks_produce(tail,bindings,acc,textures,limits,U32.sub(remaining,1))

def finish(result:Result<&2,&2,Error,Accumulator>,camera:R_Camera,settings:M_Settings) -> Result<&2,&2,Error,M_Scene>:
  match result:
    case Fail{error}: Fail{error}
    case Done{Accumulator{reversed,count,layers}}:
      Done{M_Scene{camera,List.reverse(&2,M_Quad,reversed),settings}}

def produce_valid(error:String,snapshot:R_Snapshot,bindings:List<&2,Binding>,textures:U32,frame:Frame,+limits:Limits) -> Result<&2,&2,Error,M_Scene>:
  match error:
    case "":
      R_Snapshot{tick,revision,blocks,camera} = snapshot
      Frame{width,height,settings} = frame
      Limits{max_blocks,max_bindings,max_quads,max_translucent,max_tints} = limits
      finish(blocks_produce(blocks,bindings,Accumulator{[],0,0},textures,limits,max_blocks),camera,settings)
    case error: Fail{Error{error,0}}

def produce(+snapshot:R_Snapshot,+bindings:List<&2,Binding>,+texture_count:U32,+frame:Frame,+limits:Limits) -> Result<&2,&2,Error,M_Scene>:
  R_Snapshot{tick,revision,blocks,camera} = snapshot
  Limits{max_blocks,max_bindings,max_quads,max_translucent,max_tints} = limits
  produce_valid(P_choose(String,"Limits",P_choose(String,"Frame",P_choose(String,"RelativeCamera",
    P_choose(String,"TextureCount",bindings_gate(fits(Binding,bindings,max_bindings),bindings,texture_count,max_bindings,max_quads,max_tints),
      U32.is_eq(texture_count,0)),Bool.not(relative_camera(camera))),Bool.not(frame_valid(frame))),
    Bool.not(limits_valid(limits))),snapshot,bindings,texture_count,frame,limits)
